# ---------- PowerPoint helpers ----------

def iter_shapes(shapes):
    for shape in shapes:
        if shape.shape_type == MSO_SHAPE_TYPE.GROUP:
            yield from iter_shapes(shape.shapes)
        else:
            yield shape


def shape_text(shape):
    return shape.text or "" if hasattr(shape, "text") else ""


def is_photo_key(key):
    """Only explicit photo placeholders are images.

    The D-Safe template also has names such as {{1.1Pagi}} in the
    Dokumentasi columns. Those are intentionally treated as photo fields.
    """
    k = key.strip().lower()
    if k.startswith("foto"):
        return True
    return bool(re.fullmatch(r"\d+\.\d+(pagi|siang|malam)", k))


def all_placeholders(prs):
    text_keys = []
    photo_keys = []
    table_photo_slots = []

    def add_unique(items, value):
        if value not in items:
            items.append(value)

    for slide_no, slide in enumerate(prs.slides, start=1):
        for shape in iter_shapes(slide.shapes):
            if shape.shape_type == MSO_SHAPE_TYPE.TABLE:
                table = shape.table
                headers = [c.text.strip() for c in table.rows[0].cells]
                if any("dokumentasi" in h.lower() for h in headers):
                    doc_col = next(
                        (i for i, h in enumerate(headers) if "dokumentasi" in h.lower()),
                        None,
                    )
                    if doc_col is not None:
                        for row_no in range(1, len(table.rows)):
                            # Only treat actual data rows as blank-photo slots.
                            # Some template tables (e.g. Satu Hari Satu Pasal)
                            # have a second header row whose first cell is blank.
                            # That row must never receive a photo.
                            first_cell = table.cell(row_no, 0).text.strip()
                            if not first_cell or not first_cell.isdigit():
                                continue
                            cell_text = table.cell(row_no, doc_col).text.strip()
                            if not cell_text:
                                table_photo_slots.append((slide_no, row_no, doc_col))

                for row in table.rows:
                    for cell in row.cells:
                        for key in PLACEHOLDER_RE.findall(cell.text or ""):
                            if is_photo_key(key):
                                add_unique(photo_keys, key)
                            else:
                                add_unique(text_keys, key)
            else:
                for key in PLACEHOLDER_RE.findall(shape_text(shape)):
                    if is_photo_key(key):
                        add_unique(photo_keys, key)
                    else:
                        add_unique(text_keys, key)

    return text_keys, photo_keys, table_photo_slots


def replace_in_runs(shape, mapping):
    if not hasattr(shape, "text_frame") or shape.text_frame is None:
        return

    for paragraph in shape.text_frame.paragraphs:
        for run in paragraph.runs:
            old = run.text
            new = old
            for key, value in mapping.items():
                new = new.replace("{{" + key + "}}", str(value))
            if new != old:
                run.text = new

        full = "".join(run.text for run in paragraph.runs)
        if "{{" in full:
            replaced = full
            for key, value in mapping.items():
                replaced = replaced.replace("{{" + key + "}}", str(value))
            if replaced != full and paragraph.runs:
                paragraph.runs[0].text = replaced
                for run in paragraph.runs[1:]:
                    run.text = ""


def replace_string(text, mapping):
    result = text or ""
    for key, value in mapping.items():
        result = result.replace("{{" + key + "}}", str(value))
    return result


def replace_text_everywhere(prs, mapping):
    for slide in prs.slides:
        for shape in iter_shapes(slide.shapes):
            if shape.shape_type == MSO_SHAPE_TYPE.TABLE:
                for row in shape.table.rows:
                    for cell in row.cells:
                        cell.text = replace_string(cell.text, mapping)
            else:
                replace_in_runs(shape, mapping)


def delete_shape(shape):
    sp = shape._element
    sp.getparent().remove(sp)


def delete_slide(prs, slide):
    """Remove a slide and its relationship from a python-pptx Presentation."""
    sld_id_lst = prs.slides._sldIdLst
    target_id = str(slide.slide_id)
    for sld_id in list(sld_id_lst):
        if sld_id.get('id') == target_id:
            r_id = sld_id.get(qn('r:id'))
            sld_id_lst.remove(sld_id)
            prs.part.drop_rel(r_id)
            break


def _shape_contains(shape, needle):
    return hasattr(shape, 'text') and needle in (shape.text or '')


def put_photo_on_placeholder(slide, placeholder, image_bytes):
    """Use a template placeholder shape as the exact photo anchor."""
    for shape in list(iter_shapes(slide.shapes)):
        if _shape_contains(shape, placeholder):
            left, top, width, height = shape.left, shape.top, shape.width, shape.height
            delete_shape(shape)
            if image_bytes:
                add_picture_precise(slide, image_bytes, left, top, width, height)
            return True
    return False


def normalize_image_bytes(image_bytes):
    """Normalize EXIF orientation before inserting a photo into PowerPoint."""
    image = Image.open(io.BytesIO(image_bytes))
    image = ImageOps.exif_transpose(image).convert("RGB")
    out = io.BytesIO()
    image.save(out, format="JPEG", quality=95, optimize=True)
    return out.getvalue()


def add_picture_precise(slide, image_bytes, left, top, width, height):
    """Insert a normalized photo at a fixed, clean slot.

    The template's existing photo shapes are treated only as layout anchors;
    they are removed before insertion. The inserted image uses the exact slot
    dimensions defined by this application and is never dependent on the
    original shape's crop settings.
    """
    image_bytes = normalize_image_bytes(image_bytes)
    image = Image.open(io.BytesIO(image_bytes)).convert("RGB")
    iw, ih = image.size
    target_ratio = width / height
    image_ratio = iw / ih

    pic = slide.shapes.add_picture(
        io.BytesIO(image_bytes), left, top, width=width, height=height
    )

    if image_ratio > target_ratio:
        visible_fraction = target_ratio / image_ratio
        crop = (1 - visible_fraction) / 2
        pic.crop_left = crop
        pic.crop_right = crop
    elif image_ratio < target_ratio:
        visible_fraction = image_ratio / target_ratio
        crop = (1 - visible_fraction) / 2
        pic.crop_top = crop
        pic.crop_bottom = crop

    return pic


# Backward-compatible name used by table-photo insertion.
def add_picture_crop(slide, image_bytes, left, top, width, height):
    return add_picture_precise(slide, image_bytes, left, top, width, height)


