# V35.7 — Buku Kerja field mapping mengikuti template D-Safe per kegiatan.
# V34.1 — Buku Kerja menjadi sumber transaksi tunggal.
BOOK_DATA_DIR = BASE_DIR / 'data'
BOOK_DATA_FILE = BOOK_DATA_DIR / 'buku_kerja_v341.json'
BOOK_DATA_VERSION = 341
CORE_ACTIVITY_IDS = {
    'keg_1': 'Safety Talk',
    'keg_4': 'Simulasi Pelayanan Normal & Darurat',
    'keg_9': 'Pengawasan CCTV',
    'keg_10': 'Pengawasan Langsir',
}
INITIAL_ACTIVITY_IDS = {
    'keg_1','keg_2','keg_3','keg_4','keg_5','keg_6','keg_7','keg_8','keg_9','keg_10'
}
DEFAULT_BOOK_DATA = {
    'version': BOOK_DATA_VERSION,
    'station': 'STASIUN GARUT',
    'people': [],
    'activities': [
        {'id':'keg_1','title':'Safety Talk','desc':'Briefing keselamatan kerja materi IBPR.','core':True,'target':None},
        {'id':'keg_11','title':'Satu Hari Satu Pasal','desc':'Pembacaan dan pembahasan satu pasal/peraturan setiap hari.','core':True,'target':None},
        {'id':'keg_12','title':'Cek Emplasemen Oleh KS','desc':'Pemeriksaan kondisi emplasemen oleh Kepala Stasiun (KS).','core':True,'target':None},
        {'id':'keg_2','title':'Diskusi Studi Kasus','desc':'Ruang diskusi terbuka kendala teknis dan lainnya.','core':False,'target':None},
        {'id':'keg_3','title':'Sharing Session Kendala','desc':'Ruang diskusi terbuka kendala teknis dan lainnya.','core':False,'target':None},
        {'id':'keg_4','title':'Simulasi Pelayanan Normal & Darurat','desc':'Latihan penanganan kondisi normal dan gangguan.','core':True,'target':None},
        {'id':'keg_9','title':'Pengawasan CCTV','desc':'Pengawasan kegiatan melalui CCTV.','core':True,'target':None},
        {'id':'keg_10','title':'Pengawasan Langsir','desc':'Pengawasan kegiatan langsir.','core':True,'target':None},
        {'id':'keg_5','title':'Pelatihan Mental','desc':'Kuis dengan waktu terbatas.','core':False,'target':None},
        {'id':'keg_6','title':'Coaching Teknis','desc':'Pembinaan teknis Peraturan Dinas.','core':False,'target':None},
        {'id':'keg_7','title':'Leadership','desc':'Melatih PPKA menerapkan pola kepemimpinan.','core':False,'target':None},
        {'id':'keg_8','title':'Penilaian Cara Kerja & Komunikasi','desc':'Peningkatan keterampilan public speaking dan pola berpikir.','core':False,'target':None},
    ],
    'sessions': {},
}

def _book_merge(raw):
    data = deepcopy(DEFAULT_BOOK_DATA)
    if isinstance(raw, dict):
        for k in ('version','station','people','sessions'):
            if k in raw: data[k] = raw[k]
        old_acts = raw.get('activities')
        if isinstance(old_acts, list):
            # Existing system activities stay present and immutable; custom activities are preserved.
            by_id = {a.get('id'):a for a in old_acts if isinstance(a,dict)}
            for a in data['activities']:
                if a['id'] in by_id:
                    old = by_id[a['id']]
                    a['desc'] = old.get('desc', a['desc'])
                    if 'target' in old: a['target'] = old.get('target')
            for a in old_acts:
                if isinstance(a,dict) and a.get('id') not in INITIAL_ACTIVITY_IDS:
                    data['activities'].append(a)
    # Normalize master petugas: UI uses Nama + NIPP; legacy data remains compatible.
    normalized_people=[]
    for p in data.get('people',[]) or []:
        if not isinstance(p,dict): continue
        if p.get('name') and p.get('nipp') is not None:
            normalized_people.append({'short':str(p.get('nipp','')).strip(), 'full':str(p.get('name','')).strip(), 'nipp':str(p.get('nipp','')).strip()})
        else:
            q=dict(p); q['nipp']=str(q.get('nipp','')).strip(); normalized_people.append(q)
    data['people']=normalized_people
    # Enforce final system names/mapping every load.
    for aid,title in CORE_ACTIVITY_IDS.items():
        for a in data['activities']:
            if a.get('id') == aid:
                a['title']=title; a['core']=True
    data['version']=BOOK_DATA_VERSION
    return data

def load_book_data():
    try:
        if BOOK_DATA_FILE.exists():
            return _book_merge(json.loads(BOOK_DATA_FILE.read_text(encoding='utf-8')))
    except Exception:
        pass
    return deepcopy(DEFAULT_BOOK_DATA)

def save_book_data(data):
    BOOK_DATA_DIR.mkdir(parents=True, exist_ok=True)
    BOOK_DATA_FILE.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding='utf-8')

def _img_bytes(uploaded):
    if uploaded is None: return None
    try:
        img = ImageOps.exif_transpose(Image.open(io.BytesIO(uploaded.getvalue() if hasattr(uploaded,'getvalue') else uploaded))).convert('RGB')
        img.thumbnail((1400,1400))
        b=io.BytesIO(); img.save(b, format='JPEG', quality=82, optimize=True); return b.getvalue()
    except Exception:
        return uploaded.getvalue() if hasattr(uploaded,'getvalue') else uploaded

def _b64(b): return base64.b64encode(b).decode('ascii') if b else None

def _from_b64(v):
    try: return base64.b64decode(v) if v else None
    except Exception: return None

def _book_sessions_flat(data, activity_id=None, start=None, end=None):
    rows=[]
    for aid, arr in (data.get('sessions') or {}).items():
        if activity_id and aid != activity_id: continue
        act=next((a for a in data['activities'] if a.get('id')==aid), {'id':aid,'title':aid})
        for s in arr or []:
            try: d=date.fromisoformat(s.get('date',''))
            except Exception: continue
            if start and d<start: continue
            if end and d>end: continue
            rows.append((d,act,s))
    rows.sort(key=lambda x:(x[0],x[2].get('createdAt',0)), reverse=True)
    return rows

def _person_name(data, key):
    return next((p.get('full') or p.get('name') or key for p in data.get('people',[]) if p.get('short')==key or p.get('nipp')==key), key)

def _person_nipp(data, key):
    return next((p.get('nipp','') for p in data.get('people',[]) if p.get('short')==key or p.get('nipp')==key), '')

def _members_names(data, members):
    # Unified display for activity data and all generated/printed outputs.
    # Preserve the exact capitalization entered in Master Petugas.
    out=[]
    for x in (members or []):
        name=_person_name(data,x)
        nipp=_person_nipp(data,x)
        out.append(f'{name} / {nipp}' if nipp else name)
    return ', '.join(out)

def _selected_people_widget(data, selected):
    opts=[p['short'] for p in data['people']]
    return st.multiselect('Daftar petugas', opts, default=[x for x in selected if x in opts], format_func=lambda x: _person_name(data,x))

SIGNATURE_ACTIVITY_TITLES = {
    'safety talk',
    'diskusi studi kasus',
    'sharing session kendala',
    # V36.4.43: Pelatihan Mental tidak memakai canvas/input TTD.
    'simulasi pelayanan normal & darurat',
    'coaching teknis',
    'penilaian cara kerja & komunikasi',
    'pelatihan cara kerja dan komunikasi',
    'leadership',
}

def _signature_activity_allowed(activity_title):
    """Return True only for Buku Kerja activities that require TTD.

    TTD is a Buku Kerja record only; it is intentionally never mapped into
    either PowerPoint generator. The aliases below also tolerate the wording
    used by the UI/specification (for example 'Sharing season kendala').
    """
    key=' '.join(str(activity_title or '').strip().lower().split())
    if key in SIGNATURE_ACTIVITY_TITLES:
        return True
    aliases={
        'sharing season kendala':'sharing session kendala',
        'sharing sesi kendala':'sharing session kendala',
        'simulasi':'simulasi pelayanan normal & darurat',
    }
    return aliases.get(key, key) in SIGNATURE_ACTIVITY_TITLES

def _signature_inputs(data, selected, saved=None, prefix='booksig', activity_title=None):
    saved=saved or {}
    sigs=dict(saved)
    if not _signature_activity_allowed(activity_title):
        return sigs
    if not selected:
        return sigs
    if st_canvas is None:
        for person in selected:
            up=st.file_uploader(f'TTD — {_person_name(data,person)}', type=['png','jpg','jpeg'], key=f'{prefix}_{person}')
            if up is not None: sigs[person]=_b64(_img_bytes(up))
            if sigs.get(person): st.image(_from_b64(sigs[person]), width=220)
        return sigs
    for person in selected:
        label=_person_name(data,person)
        edit_key=f'{prefix}_{person}_edit_count'
        with st.container(border=True, key=f'bk_signature_box_{prefix}_{person}'):
            label_col,edit_col=st.columns([5,1],vertical_alignment='center')
            with label_col:
                st.markdown(f'**TTD — {html.escape(label)}**')
            with edit_col:
                if st.form_submit_button('✎',key=f'{prefix}_{person}_edit'):
                    st.session_state[edit_key]=st.session_state.get(edit_key,0)+1
                    sigs.pop(person,None)
            c=st_canvas(stroke_width=2, stroke_color='#17324d', background_color='#ffffff',
                        height=110, width=300, drawing_mode='freedraw', display_toolbar=False,
                        key=f'{prefix}_{person}_{st.session_state.get(edit_key,0)}')
            if c.image_data is not None and (c.json_data or {}).get('objects'):
                try:
                    import numpy as np
                    arr=np.asarray(c.image_data).astype('uint8')
                    if arr[:,:,3].max()>0:
                        im=Image.fromarray(arr,'RGBA'); bb=io.BytesIO(); im.save(bb,format='PNG'); sigs[person]=_b64(bb.getvalue())
                except Exception: pass
            if sigs.get(person):
                st.caption('TTD tersimpan')
                st.image(_from_b64(sigs[person]), width=140)
    return sigs

def _save_session_from_form(data, sid, activity_id, d, note, members, photos, signatures):
    session={'id':sid or ('sess_'+hashlib.sha1(f'{datetime.now().timestamp()}'.encode()).hexdigest()[:12]),'date':d.isoformat(),'note':note.strip(),'members':members,'photos':[_b64(x) for x in photos if x],'signatures':signatures,'createdAt':datetime.now().timestamp()}
    # Remove old copy when editing.
    if sid:
        for aid,arr in data['sessions'].items():
            data['sessions'][aid]=[x for x in arr if x.get('id')!=sid]
    data['sessions'].setdefault(activity_id,[]).append(session)
    save_book_data(data)

def _book_pdf(data, start=None, end=None, activity_id=None):
    """Cetak Buku Kerja dalam format laporan lama.

    V36.4.14:
    - A5 landscape, maksimal 4 kegiatan per lembar.
    - Kolom NO / YA / TIDAK rata tengah.
    - Kolom KETERANGAN hanya berisi foto dokumentasi, tanpa teks.
    - Foto diperkecil proporsional sesuai orientasi agar tetap jelas dan
      tidak keluar dari area kolom KETERANGAN.
    - TTD ditampilkan sebagai gambar di kolom RENCANA KERJA, tepat di bawah
      nama kegiatan, dengan ukuran ringkas agar tidak menghabiskan ruang.
    """
    rows = _book_sessions_flat(data, activity_id, start, end)
    # V36.4.44: seluruh Kegiatan Lainnya pada tanggal yang sama ditampilkan
    # sebagai SATU baris Buku Kerja. Penyimpanan sesi tetap terpisah agar
    # masing-masing kegiatan masih dapat diedit/dihapus secara individual.
    display_rows = _book_group_other_same_day(rows)
    bio = io.BytesIO()
    doc = SimpleDocTemplate(
        bio,
        pagesize=landscape(A5),
        leftMargin=18, rightMargin=18, topMargin=18, bottomMargin=18,
        title=_report_download_filename('Buku Kerja', data.get('station'),
                                        _report_date_range(start, end), 'pdf').removesuffix('.pdf')
              if start and end else 'Buku Kerja - Program dan Realisasi Kerja',
        author='D-Safe PowerPoint Generator',
    )

    styles = getSampleStyleSheet()
    title_style = styles['Title'].clone('bk_pdf_title_v36414')
    title_style.fontName = 'Helvetica-Bold'
    title_style.fontSize = 11
    title_style.leading = 13
    title_style.alignment = 1
    title_style.textColor = colors.black

    small = styles['Normal'].clone('bk_pdf_small_v36414')
    small.fontName = 'Helvetica'
    small.fontSize = 6.0
    small.leading = 7.2
    small.textColor = colors.black

    small_bold = small.clone('bk_pdf_small_bold_v36414')
    small_bold.fontName = 'Helvetica-Bold'

    tiny = styles['Normal'].clone('bk_pdf_tiny_v36414')
    tiny.fontName = 'Helvetica'
    tiny.fontSize = 5.2
    tiny.leading = 6.1
    tiny.textColor = colors.black

    header_style = small_bold.clone('bk_pdf_header_v36414')
    header_style.fontName = 'Helvetica-Bold'
    header_style.fontSize = 6.2
    header_style.leading = 7
    header_style.alignment = 1
    header_style.textColor = colors.black

    center_small = small_bold.clone('bk_pdf_center_small_v36415')
    center_small.alignment = 1

    if not display_rows:
        display_rows = [(None, [({'id':'','title':'Buku Kerja'}, None)])]

    def _photo_flow(b64):
        """Return one proportional reportlab image for KETERANGAN."""
        raw = _from_b64(b64)
        if not raw:
            return None
        try:
            pil_im = Image.open(io.BytesIO(raw))
            iw, ih = pil_im.size
            if not iw or not ih:
                return None
            # The KETERANGAN column is about 156 pt wide.  Use orientation-aware
            # standard bounds while always preserving the original aspect ratio.
            if iw >= ih:          # landscape
                max_w, max_h = 72.0, 46.0
            else:                  # portrait
                max_w, max_h = 48.0, 62.0
            scale = min(max_w / iw, max_h / ih)
            return RLImage(io.BytesIO(raw), width=max(1.0, iw * scale),
                           height=max(1.0, ih * scale))
        except Exception:
            return None

    def _shsp_photo_row(photo_slots):
        """Satu Hari Satu Pasal: keep Pagi/Siang/Malam in one horizontal row."""
        slots=list(photo_slots or [])[:3]
        while len(slots) < 3:
            slots.append('')
        cells=[]
        for b64 in slots:
            raw=_from_b64(b64) if b64 else None
            if not raw:
                cells.append('')
                continue
            try:
                pil_im=Image.open(io.BytesIO(raw))
                iw,ih=pil_im.size
                if not iw or not ih:
                    cells.append('')
                    continue
                # Three fixed slots must fit inside the 156 pt KETERANGAN column.
                # Preserve aspect ratio while keeping every photo on the same row.
                max_w,max_h=47.0,68.0
                scale=min(max_w/iw,max_h/ih)
                cells.append(RLImage(io.BytesIO(raw),width=max(1.0,iw*scale),height=max(1.0,ih*scale)))
            except Exception:
                cells.append('')
        t=Table([cells],colWidths=[50,50,50],hAlign='CENTER')
        t.setStyle(TableStyle([
            ('ALIGN',(0,0),(-1,-1),'CENTER'),
            ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
            ('LEFTPADDING',(0,0),(-1,-1),0),
            ('RIGHTPADDING',(0,0),(-1,-1),0),
            ('TOPPADDING',(0,0),(-1,-1),0),
            ('BOTTOMPADDING',(0,0),(-1,-1),0),
        ]))
        return t

    def _cek_emplasemen_photo_grid(photo_slots):
        """Cek Emplasemen: maksimal 8 foto dalam grid ringkas 4 x 2.

        Grid khusus ini mencegah delapan foto tersusun vertikal sehingga tinggi
        satu baris tabel melebihi tinggi halaman A5 landscape. Foto tetap
        proporsional dan hanya area KETERANGAN yang diubah.
        """
        photos=[b64 for b64 in (photo_slots or []) if b64][:8]
        if not photos:
            return ''
        cells=[]
        for b64 in photos:
            raw=_from_b64(b64)
            if not raw:
                cells.append('')
                continue
            try:
                pil_im=Image.open(io.BytesIO(raw))
                iw,ih=pil_im.size
                if not iw or not ih:
                    cells.append('')
                    continue
                # Empat slot harus muat pada kolom KETERANGAN 156 pt.
                # Batas persegi menjaga tinggi maksimum dua baris tetap aman.
                max_w,max_h=34.0,34.0
                scale=min(max_w/iw,max_h/ih)
                cells.append(RLImage(io.BytesIO(raw),
                                     width=max(1.0,iw*scale),
                                     height=max(1.0,ih*scale)))
            except Exception:
                cells.append('')
        grid=[]
        for i in range(0,len(cells),4):
            row=cells[i:i+4]
            while len(row)<4:
                row.append('')
            grid.append(row)
        t=Table(grid,colWidths=[37.5,37.5,37.5,37.5],hAlign='CENTER')
        t.setStyle(TableStyle([
            ('ALIGN',(0,0),(-1,-1),'CENTER'),
            ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
            ('LEFTPADDING',(0,0),(-1,-1),0),
            ('RIGHTPADDING',(0,0),(-1,-1),0),
            ('TOPPADDING',(0,0),(-1,-1),1),
            ('BOTTOMPADDING',(0,0),(-1,-1),1),
        ]))
        return t

    def _other_same_day_photo_grid(entries):
        """Compact all Kegiatan Lainnya photos from one date in one cell.

        Four thumbnails per line keeps the combined row short enough for A5
        landscape while preserving every stored photo (max 8 per activity).
        Libur/Cuti naturally contribute no photos.
        """
        photo_values=[]
        for _activity, _sess in (entries or []):
            if not _sess:
                continue
            _key=' '.join(str((_activity or {}).get('title') or '').strip().lower().split())
            if _key in ('libur','cuti'):
                continue
            photo_values.extend([x for x in (_sess.get('photos') or []) if x][:8])
        if not photo_values:
            return ''
        cells=[]
        for b64 in photo_values:
            raw=_from_b64(b64)
            if not raw:
                continue
            try:
                pil_im=Image.open(io.BytesIO(raw))
                iw,ih=pil_im.size
                if not iw or not ih:
                    continue
                max_w,max_h=34.0,32.0
                scale=min(max_w/iw,max_h/ih)
                cells.append(RLImage(io.BytesIO(raw),
                                     width=max(1.0,iw*scale),
                                     height=max(1.0,ih*scale)))
            except Exception:
                continue
        if not cells:
            return ''
        grid=[]
        for i in range(0,len(cells),4):
            row=cells[i:i+4]
            while len(row)<4:
                row.append('')
            grid.append(row)
        t=Table(grid,colWidths=[37.5,37.5,37.5,37.5],hAlign='CENTER')
        t.setStyle(TableStyle([
            ('ALIGN',(0,0),(-1,-1),'CENTER'),
            ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
            ('LEFTPADDING',(0,0),(-1,-1),0),
            ('RIGHTPADDING',(0,0),(-1,-1),0),
            ('TOPPADDING',(0,0),(-1,-1),1),
            ('BOTTOMPADDING',(0,0),(-1,-1),1),
        ]))
        return t

    def _signature_block(signatures):
        """Compact TTD block placed under the activity title in RENCANA KERJA."""
        cells = []
        for person, b64 in (signatures or {}).items():
            raw = _from_b64(b64)
            if not raw:
                continue
            try:
                pil_im = Image.open(io.BytesIO(raw))
                iw, ih = pil_im.size
                if not iw or not ih:
                    continue
                max_w, max_h = 42.0, 15.0
                scale = min(max_w / iw, max_h / ih)
                sw = max(1.0, iw * scale)
                sh = max(1.0, ih * scale)
                cells.append([
                    Paragraph(html.escape(f"{_person_name(data, person)} / {_person_nipp(data, person)}" if _person_nipp(data, person) else _person_name(data, person)), tiny),
                    RLImage(io.BytesIO(raw), width=sw, height=sh),
                ])
            except Exception:
                continue
        if not cells:
            return None
        # 2 signatures per row keeps the TTD visible without taking over the row.
        rows_sig = []
        for i in range(0, len(cells), 2):
            chunk = cells[i:i+2]
            while len(chunk) < 2:
                chunk.append('')
            rows_sig.append(chunk)
        sig_table = Table(rows_sig, colWidths=[72, 72], hAlign='LEFT')
        sig_table.setStyle(TableStyle([
            ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
            ('LEFTPADDING', (0,0), (-1,-1), 0),
            ('RIGHTPADDING', (0,0), (-1,-1), 3),
            ('TOPPADDING', (0,0), (-1,-1), 0),
            ('BOTTOMPADDING', (0,0), (-1,-1), 1),
            ('ALIGN', (0,0), (-1,-1), 'LEFT'),
        ]))
        return sig_table

    # Nomor laporan dihitung sekali untuk seluruh hasil cetak agar tidak
    # kembali ke 1 hanya karena berganti halaman. Nomor reset saat bulan
    # kegiatan berubah, sesuai bulan pada tanggal kegiatan.
    numbered_sessions = []
    current_month = None
    current_month_no = 0
    for d, entries in display_rows:
        month_key = (d.year, d.month) if d else None
        if month_key != current_month:
            current_month = month_key
            current_month_no = 1 if month_key is not None else 0
        elif month_key is not None:
            current_month_no += 1
        report_no = current_month_no if month_key is not None else ''
        numbered_sessions.append((report_no, d, entries))

    # V36.4.41: pagination PDF Buku Kerja bersifat dinamis, tetapi tetap
    # maksimal 4 kegiatan per lembar. Sebelumnya data dipotong kaku per 4
    # kegiatan. Jika satu kelompok 4 baris terlalu tinggi, ReportLab bisa
    # memecahnya menjadi 3+1 halaman, lalu PageBreak manual membuat kegiatan
    # berikutnya pindah lagi ke halaman baru. Akibatnya satu halaman bisa hanya
    # berisi nomor 4 dan nomor 5 berada sendiri di halaman berikutnya.
    #
    # Sekarang setiap halaman diisi sebanyak mungkin (maks. 4) berdasarkan
    # tinggi aktual tabel. Jika halaman pertama hanya muat 3 baris, halaman
    # berikutnya dimulai dari nomor 4 dan akan ikut menampung nomor 5, 6, dst.
    # selama masih muat dan tidak melebihi 4 kegiatan.

    header_top = [
        Paragraph('NO', header_style),
        Paragraph('HARI / TANGGAL', header_style),
        Paragraph('RENCANA KERJA', header_style),
        Paragraph('REALISASI', header_style),
        '',
        Paragraph('KETERANGAN', header_style),
    ]
    header_bottom = ['', '', '', Paragraph('YA', header_style),
                     Paragraph('TIDAK', header_style), '']
    header_numbers = [
        Paragraph('1', header_style),
        Paragraph('2', header_style),
        Paragraph('3', header_style),
        Paragraph('4', header_style),
        Paragraph('5', header_style),
        Paragraph('6', header_style),
    ]
    col_widths = [43, 81, 183, 38, 38, 156]

    def _make_book_table(body_rows):
        table = Table(
            [header_top, header_bottom, header_numbers] + body_rows,
            colWidths=col_widths,
            repeatRows=3,
            hAlign='CENTER',
            splitByRow=1,
        )
        table.setStyle(TableStyle([
            ('BACKGROUND', (0,0), (-1,2), colors.HexColor('#22c55e')),
            ('FONTNAME', (0,2), (-1,2), 'Helvetica-Bold'),
            ('ALIGN', (0,2), (-1,2), 'CENTER'),
            ('TEXTCOLOR', (0,0), (-1,-1), colors.black),
            ('FONTNAME', (0,0), (-1,1), 'Helvetica-Bold'),
            ('ALIGN', (0,0), (-1,1), 'CENTER'),
            ('ALIGN', (0,2), (0,-1), 'CENTER'),
            ('ALIGN', (3,2), (4,-1), 'CENTER'),
            ('SPAN', (0,0), (0,1)),
            ('SPAN', (1,0), (1,1)),
            ('SPAN', (2,0), (2,1)),
            ('SPAN', (3,0), (4,0)),
            ('SPAN', (5,0), (5,1)),
            ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
            ('GRID', (0,0), (-1,-1), 0.45, colors.black),
            ('LEFTPADDING', (0,0), (-1,-1), 3),
            ('RIGHTPADDING', (0,0), (-1,-1), 3),
            ('TOPPADDING', (0,0), (-1,-1), 3),
            ('BOTTOMPADDING', (0,0), (-1,-1), 3),
        ]))
        return table

    def _session_to_body_row(report_no, d, entries):
        if not entries or entries[0][1] is None:
            return [
                Paragraph('-', center_small), Paragraph('-', small_bold),
                Paragraph('Belum ada data', small), Paragraph('', center_small),
                Paragraph('', center_small), ''
            ]

        # Khusus Kegiatan Lainnya: semua kegiatan pada hari yang sama berada
        # di satu baris/nomor. Judul kegiatan ditumpuk di sel RENCANA KERJA dan
        # seluruh dokumentasi berada pada satu sel KETERANGAN tanpa garis
        # pemisah tambahan.
        if all(_book_is_other_activity(activity) for activity, _sess in entries):
            plan_flow=[]
            for idx, (activity, _sess) in enumerate(entries):
                if idx:
                    plan_flow.append(Spacer(1, 2))
                plan_flow.append(Paragraph(f'<b>{html.escape(str(activity.get("title") or ""))}</b>', tiny))
            photo_grid=_other_same_day_photo_grid(entries)
            return [
                Paragraph(str(report_no), center_small),
                Paragraph(format_activity_date_id(d), small_bold),
                plan_flow,
                Paragraph('✓', center_small),
                Paragraph('', small),
                photo_grid,
            ]

        activity, sess = entries[0]
        title = str(activity.get('title') or '')
        activity_key = str(activity.get('id') or sess.get('activityId') or '')
        members = _members_names(data, sess.get('members', []))
        note = str(sess.get('note') or '').strip()
        key = ' '.join(title.lower().split())
        # V36.4.42 — Pengawasan Langsir harus selalu ikut ke Cetak/PDF Buku
        # Kerja dengan format khusus: hanya nama kegiatan, tanggal, status YA,
        # dan satu foto dokumentasi. Data lama yang memakai id resmi keg_10
        # tetap dikenali walaupun judul aktivitas pernah berubah.
        if activity_key == 'keg_10':
            key = 'pengawasan langsir'
            title = 'Pengawasan Langsir'

        plan_flow = [Paragraph(f'<b>{title}</b>', tiny)]
        if members and key != 'pengawasan langsir':
            plan_flow.append(Paragraph(f'<b>Petugas:</b> {members}', tiny))

        if key == 'safety talk':
            f = _parse_safety_note(note)
            if f['bahaya']:
                plan_flow.append(Paragraph(f'<b>Potensi Bahaya:</b> {f["bahaya"]}', tiny))
            if f['risiko']:
                plan_flow.append(Paragraph(f'<b>Risiko:</b> {f["risiko"]}', tiny))
            if f['kontrol']:
                plan_flow.append(Paragraph(f'<b>Cara Pengendalian:</b> {f["kontrol"]}', tiny))
        elif key == 'pengawasan cctv':
            f = _parse_cctv_note(note)
            if f['hasil']:
                plan_flow.append(Paragraph(f'<b>Hasil Pengawasan:</b> {f["hasil"]}', tiny))
            if f['tl']:
                plan_flow.append(Paragraph(f'<b>Tindak Lanjut:</b> {f["tl"]}', tiny))
        elif key == 'simulasi pelayanan normal & darurat':
            f = _parse_simulation_note(note)
            if f['keterangan']:
                plan_flow.append(Paragraph(f'<b>Keterangan:</b> {f["keterangan"]}', tiny))
            if f['materi']:
                plan_flow.append(Paragraph(f'<b>Materi Simulasi:</b> {f["materi"]}', tiny))
        elif note and key != 'pengawasan langsir':
            plan_flow.append(Paragraph(f'<b>Catatan:</b> {note}', tiny))

        # Pengawasan Langsir dan Pelatihan Mental tidak memakai TTD pada Buku Kerja.
        sig_block = None if key in ('pengawasan langsir','pelatihan mental') else _signature_block(sess.get('signatures') or {})
        if sig_block is not None:
            plan_flow.append(Spacer(1, 2))
            plan_flow.append(sig_block)

        if key in ('libur','cuti'):
            # V36.4.43: Libur/Cuti tidak menampilkan dokumentasi di Cetak/PDF.
            photo_flow = []
        elif key == 'satu hari satu pasal':
            photo_flow = _shsp_photo_row(sess.get('photos') or [])
        elif key == 'cek emplasemen oleh ks':
            photo_flow = _cek_emplasemen_photo_grid(sess.get('photos') or [])
        elif key == 'pengawasan langsir':
            # Satu kegiatan Langsir = tepat satu foto di kolom KETERANGAN.
            # Tidak ada uraian, petugas, atau tanda tangan.
            photo_flow = []
            first_photo = next((x for x in (sess.get('photos') or []) if x), None)
            if first_photo:
                img = _photo_flow(first_photo)
                if img is not None:
                    photo_flow.append(img)
        else:
            photo_flow = []
            for b64 in (sess.get('photos') or [])[:8]:
                img = _photo_flow(b64)
                if img is not None:
                    if photo_flow:
                        photo_flow.append(Spacer(1, 2))
                    photo_flow.append(img)

        return [
            Paragraph(str(report_no), center_small),
            Paragraph(format_activity_date_id(d), small_bold),
            plan_flow,
            Paragraph('✓', center_small),
            Paragraph('', small),
            photo_flow,
        ]

    all_body_rows = [
        _session_to_body_row(report_no, d, entries)
        for report_no, d, entries in numbered_sessions
    ]

    story = []
    title_probe = Paragraph('PROGRAM DAN REALISASI KERJA KEPALA STASIUN', title_style)
    _, title_h = title_probe.wrap(doc.width, doc.height)
    # Sedikit toleransi untuk Spacer dan perhitungan rounding ReportLab.
    max_table_h = max(40, doc.height - title_h - 9)

    page_start = 0
    while page_start < len(all_body_rows):
        take = min(4, len(all_body_rows) - page_start)
        # Cari jumlah terbesar (maks. 4) yang benar-benar muat pada satu halaman.
        while take > 1:
            probe = _make_book_table(all_body_rows[page_start:page_start + take])
            _, probe_h = probe.wrap(doc.width, max_table_h)
            if probe_h <= max_table_h:
                break
            take -= 1

        page_body = all_body_rows[page_start:page_start + take]
        story.append(Paragraph('PROGRAM DAN REALISASI KERJA KEPALA STASIUN', title_style))
        story.append(Spacer(1, 6))
        story.append(_make_book_table(page_body))

        page_start += take
        if page_start < len(all_body_rows):
            from reportlab.platypus import PageBreak
            story.append(PageBreak())

    doc.build(story)
    bio.seek(0)
    return bio.getvalue()

def render_buku_kerja_v341():
    data=load_book_data(); st.session_state['_book_data']=data
    # Aksi Riwayat Kegiatan memakai link HTML agar tombol tetap berada di
    # samping dokumentasi tanpa menambah elemen Streamlit yang berulang.
    # Ini juga mencegah duplicate element key ketika satu sesi muncul lebih
    # dari sekali pada hasil riwayat.
    try:
        _q_edit=st.query_params.get('bk_edit')
        _q_delete=st.query_params.get('bk_delete')
        if _q_delete:
            if any(s.get('id') == _q_delete for arr in (data.get('sessions') or {}).values() for s in (arr or [])):
                _delete_session(data,_q_delete)
            try: del st.query_params['bk_delete']
            except Exception: pass
            st.rerun()
        if _q_edit:
            if any(s.get('id') == _q_edit for arr in (data.get('sessions') or {}).values() for s in (arr or [])):
                st.session_state['bk_edit']=_q_edit
                st.session_state['bk_form_open']=True
            try: del st.query_params['bk_edit']
            except Exception: pass
            st.rerun()
    except Exception:
        pass
    st.markdown("<div class='app-theme-bar'><div class='app-brand'><div class='app-brand-mark'>📖</div><div><div class='app-brand-title'>Buku Kerja</div><div class='app-brand-sub'>Pusat input seluruh kegiatan</div></div></div><div class='app-status'>● Tersimpan lokal</div></div>",unsafe_allow_html=True)
    a,b=st.columns([1,1])
    with a:
        if st.button('＋ Input Kegiatan',type='primary',use_container_width=True,key='bk_add'):
            st.session_state['bk_edit']=None; st.session_state['bk_form_open']=True; st.rerun()
    with b:
        if st.button('🖨 Cetak / PDF',use_container_width=True,key='bk_pdf'):
            st.session_state['bk_pdf_open']=True
    if st.session_state.get('bk_form_open'):
        edit=st.session_state.get('bk_edit'); old=None; old_aid=None
        if edit:
            for aid0,arr in data['sessions'].items():
                old=next((x for x in arr if x.get('id')==edit),None)
                if old: old_aid=aid0; break
        st.markdown('### Input / Edit Kegiatan')
        with st.form('book_form',clear_on_submit=False):
            acts=[a for a in data['activities']]
            aid_default=(old.get('activityId') if old and old.get('activityId') else old_aid) if old else acts[0]['id']
            # activityId is added below for convenience when editing old records.
            titles=[a['title'] for a in acts]; idx=next((i for i,a in enumerate(acts) if a['id']==aid_default),0)
            title=st.selectbox('Kegiatan',titles,index=idx)
            aid=acts[titles.index(title)]['id']
            d=st.date_input('Tanggal',date.fromisoformat(old['date']) if old and old.get('date') else date.today(),format='DD/MM/YYYY')
            note=st.text_area('Uraian Kegiatan',value=old.get('note','') if old else '',placeholder='Uraian kegiatan / hasil pelaksanaan')
            selected=_selected_people_widget(data,old.get('members',[]) if old else [], key=f'bk_people_widget_{form_token}_{aid}')
            photos=[]
            ups=st.file_uploader('Dokumentasi',type=['jpg','jpeg','png','webp'],accept_multiple_files=True,key='bk_photos_edit')
            if ups:
                seen=set()
                for up in ups[:8]:
                    bb=_img_bytes(up); h=hashlib.sha256(bb).hexdigest()
                    if h not in seen: photos.append(bb); seen.add(h)
            old_photos=[_from_b64(x) for x in (old.get('photos',[]) if old else []) if x]
            if old_photos: st.caption(f'{len(old_photos)} foto lama tersimpan. Upload baru akan menggantinya.')
            signatures=_signature_inputs(data,selected,old.get('signatures',{}) if old else {},prefix='bk_sig_'+str(edit or 'new'),activity_title=title)
            c1,c2=st.columns(2)
            with c1: save=st.form_submit_button('💾 Simpan Kegiatan',type='primary',use_container_width=True)
            with c2: cancel=st.form_submit_button('Batal',use_container_width=True)
        if cancel:
            st.session_state['bk_form_open']=False; st.rerun()
        if save:
            final_photos=photos if photos else old_photos
            _save_session_from_form(data,edit,aid,d,note,selected,final_photos,signatures)
            # attach stable activity id to the record just saved
            data=load_book_data(); target=data['sessions'][aid][-1]; target['activityId']=aid; save_book_data(data)
            st.session_state['bk_form_open']=False; st.success('Kegiatan tersimpan.'); st.rerun()
    if st.session_state.get('bk_pdf_open'):
        st.markdown('### Cetak / PDF')
        c1,c2,c3=st.columns(3)
        with c1: rs=st.date_input('Mulai',date(date.today().year,date.today().month,1),format='DD/MM/YYYY',key='bk_rs')
        with c2: re_=st.date_input('Sampai',date.today(),format='DD/MM/YYYY',key='bk_re')
        with c3:
            opts=['Semua Kegiatan']+[a['title'] for a in data['activities']]
            sel=st.selectbox('Jenis Kegiatan',opts,key='bk_ra')
        aid=next((a['id'] for a in data['activities'] if a['title']==sel),None)
        pdf=_book_pdf(data,rs,re_,aid)
        st.download_button('⬇️ Download PDF Buku Kerja',pdf,
                           _report_download_filename('Buku Kerja',data.get('station'),_report_date_range(rs,re_),'pdf'),
                           'application/pdf',use_container_width=True,key='bk_pdf_dl')
    st.markdown('### Riwayat Kegiatan')
    # Always re-read the source file immediately before rendering the history.
    # This removes any dependency on the copy of `data` that existed before a
    # form submit in the current Streamlit run.
    data=load_book_data()
    st.session_state['_book_data']=data
    rows=_book_sessions_flat(data)
    if not rows:
        st.info('Belum ada kegiatan.')
    else:
        import html as _html
        def _hist_sig_html(signatures):
            items=[]
            for person,b64 in (signatures or {}).items():
                raw=_from_b64(b64)
                if not raw: continue
                try:
                    src='data:image/png;base64,'+base64.b64encode(raw).decode('ascii')
                    items.append(f'<div style="display:inline-flex;flex-direction:column;align-items:center;margin-right:8px;vertical-align:bottom;">'
                                 f'<img src="{src}" style="max-width:48px;max-height:18px;object-fit:contain;display:block;">'
                                 f'<span style="font-size:8px;font-weight:600;line-height:1.1;">{_html.escape(str(person))}</span></div>')
                except Exception:
                    continue
            return ''.join(items)

        def _hist_photo_html(photos):
            out=[]
            for b64 in (photos or [])[:8]:
                raw=_from_b64(b64)
                if not raw: continue
                try:
                    pil=Image.open(io.BytesIO(raw)); w,h=pil.size
                    if w>=h: mw,mh=82,52
                    else: mw,mh=52,68
                    scale=min(mw/w,mh/h)
                    src='data:image/png;base64,'+base64.b64encode(raw).decode('ascii')
                    out.append(f'<img src="{src}" style="width:{max(1,w*scale):.1f}px;height:{max(1,h*scale):.1f}px;object-fit:contain;vertical-align:top;margin:1px 3px 1px 0;border:1px solid #999;">')
                except Exception:
                    continue
            return ''.join(out)

        hrows=[]
        hist_month=None
        hist_no=0
        for d,a,s in rows:
            mk=(d.year,d.month)
            if mk != hist_month:
                hist_month=mk; hist_no=1
            else:
                hist_no += 1
            title=str(a.get('title',''))
            key=' '.join(title.lower().split())
            members=_members_names(data,s.get('members',[]))
            note=str(s.get('note') or '').strip()
            plan=[f'<b>{_html.escape(title)}</b>']
            if members: plan.append(f'<b>Petugas:</b> {_html.escape(members)}')
            if key=='safety talk':
                f=_parse_safety_note(note)
                if f['bahaya']: plan.append(f'<b>Potensi Bahaya:</b> {_html.escape(f["bahaya"])}')
                if f['risiko']: plan.append(f'<b>Risiko:</b> {_html.escape(f["risiko"])}')
                if f['kontrol']: plan.append(f'<b>Cara Pengendalian:</b> {_html.escape(f["kontrol"])}')
            elif key=='pengawasan cctv':
                f=_parse_cctv_note(note)
                if f['hasil']: plan.append(f'<b>Hasil Pengawasan:</b> {_html.escape(f["hasil"])}')
                if f['tl']: plan.append(f'<b>Tindak Lanjut:</b> {_html.escape(f["tl"])}')
            elif key=='simulasi pelayanan normal & darurat':
                f=_parse_simulation_note(note)
                if f['keterangan']: plan.append(f'<b>Keterangan:</b> {_html.escape(f["keterangan"])}')
                if f['materi']: plan.append(f'<b>Materi Simulasi:</b> {_html.escape(f["materi"])}')
            elif note:
                plan.append(f'<b>Catatan:</b> {_html.escape(note)}')
            sig=_hist_sig_html(s.get('signatures') or {})
            if sig: plan.append(f'<div style="margin-top:3px;border-top:1px solid #aaa;padding-top:2px;">{sig}</div>')
            photos=_hist_photo_html(s.get('photos'))
            hrows.append(f'<tr>'
                         f'<td class="c">{hist_no}</td>'
                         f'<td class="c">{_html.escape(format_activity_date_id(d))}</td>'
                         f'<td>{"<br>".join(plan)}</td>'
                         f'<td class="c">✓</td><td class="c"></td>'
                         f'<td>{photos}</td></tr>')

        history_html='''<div style="overflow-x:auto;margin-top:6px;">
<table style="width:100%;border-collapse:collapse;table-layout:fixed;font-size:10px;line-height:1.15;color:#111;">
<thead>
<tr style="background:#22c55e;font-weight:800;text-align:center;">
<th rowspan="2" style="width:6%;border:1px solid #111;padding:4px;">NO</th>
<th rowspan="2" style="width:15%;border:1px solid #111;padding:4px;">HARI/TANGGAL</th>
<th rowspan="2" style="width:34%;border:1px solid #111;padding:4px;">RENCANA KERJA</th>
<th colspan="2" style="width:14%;border:1px solid #111;padding:4px;">REALISASI</th>
<th rowspan="2" style="width:31%;border:1px solid #111;padding:4px;">KETERANGAN</th>
</tr>
<tr style="background:#22c55e;font-weight:800;text-align:center;">
<th style="width:7%;border:1px solid #111;padding:4px;">YA</th>
<th style="width:7%;border:1px solid #111;padding:4px;">TIDAK</th>
</tr>
<tr style="background:#22c55e;font-weight:800;text-align:center;">
<th style="border:1px solid #111;padding:3px;">1</th><th style="border:1px solid #111;padding:3px;">2</th><th style="border:1px solid #111;padding:3px;">3</th><th style="border:1px solid #111;padding:3px;">4</th><th style="border:1px solid #111;padding:3px;">5</th><th style="border:1px solid #111;padding:3px;">6</th>
</tr>
</thead><tbody>''' + ''.join(hrows) + '''</tbody></table></div>'''
        st.markdown(history_html,unsafe_allow_html=True)
        # Aksi tetap tersedia tanpa menambah kolom ke tabel agar format tabel identik dengan PDF.
        for d,a,s in rows:
            c1,c2,c3=st.columns([7,1,1])
            with c1: st.caption(f"{format_activity_date_id(d)} · {a.get('title','')}")
            with c2:
                if st.button('Edit',key='bk_e_'+s['id']): st.session_state['bk_edit']=s['id']; st.session_state['bk_form_open']=True; st.rerun()
            with c3:
                if st.button('Hapus',key='bk_d_'+s['id']):
                    data['sessions'][a['id']]=[x for x in data['sessions'].get(a['id'],[]) if x.get('id')!=s['id']]; save_book_data(data); st.rerun()

DASHBOARD_TARGET_RULES = (
    ('keg_1', 1, 'minggu'),   # Safety Talk
    ('keg_3', 1, 'minggu'),   # Sharing Session/Season Kendala
    ('keg_4', 1, 'minggu'),   # Simulasi Pelayanan Normal & Darurat
    ('keg_2', 1, 'minggu'),   # Diskusi Studi Kasus
    ('keg_5', 1, 'minggu'),   # Pelatihan Mental
    ('keg_6', 2, 'bulan'),    # Coaching Teknis
    ('keg_8', 1, 'bulan'),    # Penilaian Cara Kerja & Komunikasi
)

def _dashboard_target_intervals(start, end, unit, today):
    """Use whole calendar weeks/months that have already begun."""
    intervals=[]
    if unit=='minggu':
        cursor=start-timedelta(days=start.weekday())
        while cursor<=end and cursor<=today:
            intervals.append((cursor,cursor+timedelta(days=6)))
            cursor+=timedelta(days=7)
    else:
        cursor=date(start.year,start.month,1)
        while cursor<=end and cursor<=today:
            next_month=date(cursor.year+(cursor.month==12),(cursor.month%12)+1,1)
            intervals.append((cursor,next_month-timedelta(days=1)))
            cursor=next_month
    return intervals

def _render_dashboard_targets(data, start, end, period, today):
    """Seven fixed target charts; keep the established per-person calendar rules."""
    people=[p for p in data.get('people',[]) if str(p.get('key') or p.get('short') or '').strip()]
    names={a.get('id'):a.get('title','-') for a in data.get('activities',[])}
    st.markdown('<div class="dk77-target-heading"><div><span>Program Keselamatan Kepala Stasiun</span><strong>7 kegiatan terukur</strong></div><small>Hijau 100% · Jingga 50–99% · Merah 0–49% · Ungu kontribusi minggu ini</small></div>',unsafe_allow_html=True)
    if not people:
        st.info('Tambahkan petugas di Pengaturan untuk melihat capaian target per orang.')
    for cadence in ('minggu','bulan'):
        rules=[rule for rule in DASHBOARD_TARGET_RULES if rule[2]==cadence]
        st.markdown(f'<div class="dk77-cadence"><span>{"Target mingguan" if cadence=="minggu" else "Target bulanan"}</span><small>{len(rules)} kegiatan · per petugas</small></div>',unsafe_allow_html=True)
        cards=[]
        for aid,quota,_ in rules:
            title=html.escape(str(names.get(aid,aid)))
            view_only=(period=='Minggu' and cadence=='bulan')
            four_weeks=(cadence=='minggu' and period!='Minggu')
            intervals=[] if view_only else _dashboard_target_intervals(start,end,'bulan' if four_weeks else cadence,today)
            source=_book_sessions_flat(data,aid,start=start if view_only or four_weeks else None,end=end if view_only or four_weeks else None)
            entries=[]
            for d,_,session in source:
                if d>today:continue
                keys=set()
                for raw in (session.get('members') or []):
                    person=_person_by_key(data,raw)
                    if person:keys.add(str(person.get('key') or person.get('short')))
                entries.append((d,keys))
            details=[]; achieved_total=0; contribution=0
            for person in people:
                key=str(person.get('key') or person.get('short'))
                display=html.escape(str(person.get('full') or person.get('name') or key))
                nipp=html.escape(str(person.get('nipp') or ''))
                if nipp:display+=f' · {nipp}'
                if view_only:
                    count=sum(start<=d<=end and key in keys for d,keys in entries)
                    contribution+=count
                    detail=f'{count}/{quota} kali minggu ini'
                elif four_weeks:
                    counts=[]
                    for lo,hi in intervals:
                        weeks={}
                        for d,keys in entries:
                            if lo<=d<=hi and key in keys:
                                monday=d-timedelta(days=d.weekday())
                                weeks[monday]=weeks.get(monday,0)+1
                        counts.append(min(4,sum(value>=quota for value in weeks.values())))
                    met=sum(counts)
                    achieved_total+=met
                    detail=f'{met}/{4*len(intervals)} minggu tercapai' if intervals else 'Belum dimulai'
                else:
                    counts=[sum(lo<=d<=hi and key in keys for d,keys in entries) for lo,hi in intervals]
                    met=sum(count>=quota for count in counts)
                    achieved_total+=met
                    detail=(f'{counts[0]}/{quota} kali' if len(counts)==1 else
                            f'{met}/{len(counts)} {cadence} tercapai' if counts else 'Belum dimulai')
                details.append(f'<span class="dk77-person"><b>{display}</b><em>{detail}</em></span>')
            if view_only:
                denominator=len(people)*quota
                pct=min(100,round(contribution/denominator*100)) if denominator else 0
                status='monthly'; measure=f'{contribution} kali minggu ini'
            else:
                denominator=len(people)*len(intervals)*(4 if four_weeks else 1)
                pct=round(achieved_total/denominator*100) if denominator else 0
                status=('complete' if pct>=100 else 'near' if pct>=50 else 'low') if denominator else 'empty'
                measure=f'{achieved_total}/{denominator} target terpenuhi' if denominator else 'Belum dinilai'
            cards.append(f'<article class="dk77-target-card is-{status}">'
                         f'<div class="dk77-target-top"><h3>{title}</h3><span class="dk77-quota">{quota}×/{cadence}</span></div>'
                         f'<div class="dk77-target-progress"><strong>{measure}</strong><b>{pct}%</b></div>'
                         f'<div class="dk77-target-track" role="img" aria-label="{title}: {measure}"><span style="width:{pct}%"></span></div>'
                         f'<div class="dk77-people">'+''.join(details)+'</div></article>')
        st.markdown('<div class="dk77-target-grid">'+''.join(cards)+'</div>',unsafe_allow_html=True)

