def _v421_eval_pages(mode_key=None):
    # Evaluation is the only editable field on the generator cards.
    # Seed it once from the latest saved draft/source, then keep the user's
    # card edit in session state so Generate uses exactly what was reviewed.
    key = mode_key or ('full' if mode == 'full' else 'weekly')
    state_key = f'v421_eval_{key}'
    editor_key = f'v421_eval_{key}_editor'
    if editor_key in st.session_state:
        text = st.session_state.get(editor_key) or EVAL_DRAFT_DEFAULT
        st.session_state[state_key] = text
    elif state_key in st.session_state:
        text = st.session_state.get(state_key) or EVAL_DRAFT_DEFAULT
    else:
        text=EVAL_DRAFT_DEFAULT
        src=st.session_state.get('loaded_full17') or st.session_state.get('loaded_weekly17')
        if isinstance(src,dict):
            try:
                text=src.get('pages',{}).get('eval',[{}])[0].get('Hasil_Evaluasi') or src.get('general',{}).get('Hasil_Evaluasi') or text
            except Exception:
                pass
        st.session_state[state_key]=text
    return [{'Hasil_Evaluasi':text}]


def _v421_img_html(b64, max_w=150, max_h=90):
    raw=_from_b64(b64)
    if not raw:
        return ''
    try:
        im=Image.open(io.BytesIO(raw))
        iw,ih=im.size
        if not iw or not ih: return ''
        scale=min(max_w/iw,max_h/ih)
        w=max(1,int(iw*scale)); h=max(1,int(ih*scale))
    except Exception:
        w,h=max_w,max_h
    src='data:image/jpeg;base64,'+base64.b64encode(raw).decode('ascii')
    return f'<img src="{src}" style="width:{w}px;height:{h}px;object-fit:contain;border:1px solid #bbb;border-radius:4px;background:#fff;margin:3px;">'


def _v421_page_shell(title, body_html):
    return f'''<div class="v421-review-page" style="background:#fff;color:#000;border:1px solid #c9d9e8;border-radius:10px;padding:9px 10px;margin:5px 0 8px 0;box-shadow:0 2px 8px rgba(24,69,112,.07);">
      <div class="v421-review-title" style="text-align:center;font-weight:850;font-size:14px;line-height:1.15;margin-bottom:7px;color:#17324d;">{html.escape(title)}</div>
      {body_html}
    </div>'''


def _v421_table(headers, rows, widths=None):
    widths=widths or []
    h=''.join(f'<th style="border:1px solid #000;padding:3px 4px;text-align:center;background:#22c55e;line-height:1.15;">{html.escape(str(x))}</th>' for x in headers)
    rr=[]
    for row in rows:
        cells=[]
        for x in row:
            cells.append(f'<td style="border:1px solid #000;padding:3px 4px;vertical-align:top;line-height:1.22;">{x}</td>')
        rr.append('<tr>'+''.join(cells)+'</tr>')
    return '<table style="width:100%;border-collapse:collapse;font-family:Arial,sans-serif;font-size:10px;color:#000;"><thead><tr>'+h+'</tr></thead><tbody>'+''.join(rr)+'</tbody></table>'


def _v421_photo_cell(items, max_w=72, max_h=54):
    """Return a compact documentation cell with proportional thumbnails."""
    if not items:
        return '<span style="color:#777;">—</span>'
    imgs=[]
    for item in items:
        if not item:
            continue
        if isinstance(item,(bytes,bytearray)):
            b64=base64.b64encode(item).decode('ascii')
        else:
            b64=str(item)
        img=_v421_img_html(b64,max_w,max_h)
        if img: imgs.append(img)
    return '<div style="display:flex;flex-wrap:wrap;align-items:center;gap:2px;">'+''.join(imgs)+'</div>' if imgs else '<span style="color:#777;">—</span>'


def _v421_shsp_photo_cell(items, max_w=72, max_h=54):
    """Three fixed documentation slots matching Pagi / Siang / Malam."""
    slots=[]
    vals=list(items or [])[:3]
    while len(vals) < 3:
        vals.append(None)
    for item in vals:
        if item:
            b64=base64.b64encode(item).decode('ascii') if isinstance(item,(bytes,bytearray)) else str(item)
            content=_v421_img_html(b64,max_w,max_h) or '<span style="color:#777;">—</span>'
        else:
            content='<span style="color:#777;">—</span>'
        slots.append('<div class="v421-shsp-slot" style="min-height:54px;display:flex;align-items:center;justify-content:center;border-right:1px solid #ddd;">'+content+'</div>')
    return '<div class="v421-shsp-doc" style="align-items:stretch;">'+''.join(slots)+'</div>'


def _v421_get_photo(photos, key):
    v=photos.get(key)
    return v


def _v421_review_full_pages(pages, photos):
    # HTML review is intentionally the stable fallback.  It mirrors the
    # template tables and includes the same documentation photos used by PPT.
    for i,p in enumerate(pages.get('shsp',[]),1):
        rows=[]
        for r in range(1,4):
            if any(p.get(f'{r}.{k}','') for k in ('Hari_Tanggal','Jabatan','1Nama','2Nama','3Nama')):
                pics=[]
                for j,shift in enumerate(('Pagi','Siang','Malam'),1):
                    pics.append(_v421_get_photo(photos,f'shsp{i}:{r}.{j}{shift}'))
                rows.append([p.get(f'{r}.Hari_Tanggal',''),p.get(f'{r}.Jabatan',''),p.get(f'{r}.1Nama',''),p.get(f'{r}.2Nama',''),p.get(f'{r}.3Nama',''),_v421_shsp_photo_cell(pics)])
        if rows:
            st.markdown(_v421_page_shell(f'D-Safe — Satu Hari Satu Pasal — Lembar {i}',_v421_table(['Hari / Tanggal','Jabatan','Dinas Pagi','Dinas Siang','Dinas Malam','Dokumentasi'],rows)),unsafe_allow_html=True)
    for i in range(pages.get('cek_count',0)):
        pics=[]
        for n in range(1,9):
            b=_v421_get_photo(photos,f'cek{i+1}:Foto{n}')
            if b: pics.append(b)
        body='<div style="font-size:11px;margin-bottom:6px;">Dokumentasi Cek Emplasemen Oleh KS</div><div style="display:flex;flex-wrap:wrap;gap:4px;">'+_v421_photo_cell(pics,110,78)+'</div>'
        st.markdown(_v421_page_shell(f'D-Safe — Cek Emplasemen Oleh KS — Lembar {i+1}',body),unsafe_allow_html=True)
    # V36.4.40 — the preview mirrors the template: one simulation table
    # contains up to four activities. Documentation remains a separate photo
    # section pooled across the selected period, 8 photos per page.
    for i,p in enumerate(pages.get('sim',[]),1):
        rows=[]
        for r in range(1,5):
            rows.append([p.get(f'{r}.Hari_Tanggal','-'),p.get(f'{r}.Nama','-'),p.get(f'{r}.Jabatan','-'),p.get(f'{r}.Keterangan','-'),p.get(f'{r}.Materi_Simulasi','-')])
        if rows:
            st.markdown(_v421_page_shell(f'D-Safe — Simulasi Pelayanan Normal & Darurat — Lembar {i}',_v421_table(['Hari / Tanggal','Nama','Jabatan','Keterangan','Materi Simulasi'],rows)),unsafe_allow_html=True)

    sim_review_photos=[]
    simdoc_items=[]
    for key,b in photos.items():
        m=re.match(r'^simdoc:FotoS\.(\d+)$', str(key))
        if m and b:
            simdoc_items.append((int(m.group(1)),b))
    if simdoc_items:
        sim_review_photos=[b for _,b in sorted(simdoc_items)]
    else:
        # Backward-compatible fallback for older drafts.
        for i in range(1,int(pages.get('sim_count',0) or 0)+1):
            for n in range(1,9):
                b=_v421_get_photo(photos,f'sim{i}:FotoS.{n}')
                if b:
                    sim_review_photos.append(b)
    for doc_no in range(1,(len(sim_review_photos)+7)//8+1):
        chunk=sim_review_photos[(doc_no-1)*8:doc_no*8]
        cells=[]
        for b in chunk:
            b64=base64.b64encode(b).decode('ascii') if isinstance(b,(bytes,bytearray)) else str(b)
            cells.append('<div style="min-height:112px;display:flex;align-items:center;justify-content:center;background:#f8fafc;border:1px solid #d7e0e8;">'+(_v421_img_html(b64,150,105) or '')+'</div>')
        while len(cells)<8:
            cells.append('<div style="min-height:112px;background:#f8fafc;border:1px solid #e5e7eb;"></div>')
        body='<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:5px;">'+''.join(cells)+'</div>'
        st.markdown(_v421_page_shell(f'D-Safe — Dokumentasi Simulasi — Lembar {doc_no}',body),unsafe_allow_html=True)
    for i,p in enumerate(pages.get('cctv',[]),1):
        rows=[]
        for r in range(1,5):
            if any(p.get(f'{r}.{k}','') for k in ('Hari_Tanggal','Nama/_Nipp','Hasil_Pengawasan','TL')):
                b=_v421_get_photo(photos,f'cctv{i}:Foto_CCTV.{r}')
                rows.append([str(r),p.get(f'{r}.Hari_Tanggal',''),'Ruang PPKA',p.get(f'{r}.Nama/_Nipp',''),p.get(f'{r}.Hasil_Pengawasan',''),p.get(f'{r}.TL',''),_v421_photo_cell([b] if b else [])])
        if rows:
            st.markdown(_v421_page_shell(f'D-Safe — Pengawasan CCTV — Lembar {i}',_v421_table(['No','Hari / Tanggal Pengawasan','Obyek Pengawasan','Pengawasan kepada (Nama / NIPP)','Hasil Pengawasan','Tindak Lanjut','Dokumentasi'],rows)),unsafe_allow_html=True)


def _v421_review_weekly_pages(pages, photos):
    for i,p in enumerate(pages.get('ibpr',[]),1):
        body='<div style="font-weight:700;font-size:13px;margin-bottom:6px;">'+html.escape(p.get('Hari_Tanggal',''))+'</div>'
        b=photos.get(f'ibpr{i}:SafetyTalk')
        body+=_v421_table(['Peserta','Potensi Bahaya','Risiko','Cara Pengendalian','Dokumentasi'],[[html.escape(p.get('Peserta','')),html.escape(p.get('Potensi_Bahaya','')),html.escape(p.get('Risiko','')),html.escape(p.get('Cara_Pengendalian','')),_v421_photo_cell([b] if b else [])]])
        st.markdown(_v421_page_shell(f'Safety Talk Mingguan — Safety Talk / IBPR — Lembar {i}',body),unsafe_allow_html=True)
    for i,p in enumerate(pages.get('cctv',[]),1):
        rows=[]
        for r in range(1,5):
            if any(p.get(f'{r}.{k}','') for k in ('Hari_Tanggal','Nama/_Nipp','Hasil_Pengawasan','TL')):
                b=photos.get(f'weekly_cctv{i}:Foto_CCTV.{r}') or photos.get(f'cctv{i}:Foto_CCTV.{r}')
                rows.append([str(r),p.get(f'{r}.Hari_Tanggal',''),'Ruang PPKA',p.get(f'{r}.Nama/_Nipp',''),p.get(f'{r}.Hasil_Pengawasan',''),p.get(f'{r}.TL',''),_v421_photo_cell([b] if b else [])])
        if rows:
            st.markdown(_v421_page_shell(f'Safety Talk Mingguan — Pengawasan CCTV — Lembar {i}',_v421_table(['No','Hari / Tanggal Pengawasan','Obyek Pengawasan','Pengawasan kepada (Nama / NIPP)','Hasil Pengawasan','Tindak Lanjut','Dokumentasi'],rows)),unsafe_allow_html=True)
    langsir=pages.get('langsir',[]) or []
    if langsir:
        for page_no in range(1,(len(langsir)+2)//3+1):
            chunk=langsir[(page_no-1)*3:page_no*3]
            cards=[]
            for slot in range(1,4):
                if slot <= len(chunk):
                    sess=chunk[slot-1]
                    d=format_activity_date_id(_safe_date(sess.get('date'))) if sess.get('date') else ''
                    pic=_from_b64(sess.get('photos',[None])[0]) if sess.get('photos') else None
                    img=_v421_photo_cell([pic] if pic else [], 190, 126)
                else:
                    d=''; img=''
                cards.append(f'''<div class="v421-langsir-card" style="border:1px solid #d6e4ef;border-radius:10px;padding:8px;background:#fff;text-align:center;">
                    <div style="font-weight:800;font-size:11px;margin-bottom:8px;border:1px solid #8cc06c;padding:4px;">{html.escape(d)}</div>
                    <div style="min-height:132px;display:flex;align-items:center;justify-content:center;background:#f8fafc;">{img}</div>
                </div>''')
            body='<div class="v421-langsir-grid">' + ''.join(cards) + '</div>'
            st.markdown(_v421_page_shell(f'Safety Talk Mingguan — Pengawasan Langsir — Lembar {page_no}',body),unsafe_allow_html=True)


def _v421_evaluation_review(text, mode_key):
    """Single evaluation review. Edit is optional; there is deliberately no Save button."""
    state_key=f'v421_eval_{mode_key}'
    edit_key=f'v421_eval_{mode_key}_editing'
    current=st.session_state.get(state_key) or text or EVAL_DRAFT_DEFAULT
    st.session_state[state_key]=current
    with st.container(border=True):
        st.markdown('### Hasil Evaluasi')
        if not st.session_state.get(edit_key,False):
            st.markdown(f'<div style="white-space:pre-wrap;font-size:12px;line-height:1.5;border:1px solid #000;padding:12px;min-height:110px;background:#fff;color:#000;">{html.escape(current)}</div>',unsafe_allow_html=True)
            a,b=st.columns([8,2])
            with b:
                if st.button('✏️ Edit',key=f'v421_edit_eval_{mode_key}',use_container_width=True):
                    st.session_state[edit_key]=True
                    st.rerun()
        else:
            edited=st.text_area('Hasil Evaluasi',value=current,height=180,key=f'v421_eval_text_{mode_key}')
            # Streamlit's widget value becomes the source for Generate immediately.
            st.session_state[state_key]=edited


def _v421_pages_full():
    cctv=_v421_cctv_pages()
    pages={
        'shsp':_v421_shsp_pages(), 'shsp_count':int(st.session_state.get('n14_shsp',0) or 0),
        'cek':[{} for _ in range(int(st.session_state.get('n14_cek',0) or 0))], 'cek_count':int(st.session_state.get('n14_cek',0) or 0),
        'sim':_v421_sim_pages(), 'sim_count':int(st.session_state.get('n14_sim',0) or 0),
        'cctv':cctv, 'cctv_count':len(cctv),
        'eval':_v421_eval_pages('full'), 'eval_count':1
    }
    return pages


def _v421_pages_weekly():
    cctv=_v421_cctv_pages()
    # Safety Talk IBPR comes directly from filtered Buku Kerja Safety Talk.
    restored=st.session_state.get('_restored_weekly_ibpr',{}) or {}
    ibpr=[]
    for i in sorted(restored):
        d=restored[i]
        ibpr.append({'Hari_Tanggal':format_activity_date_id(d.get('date')) if d.get('date') else '',
                     'Peserta':d.get('peserta',''),'Potensi_Bahaya':d.get('bahaya',''),
                     'Risiko':d.get('risiko',''),'Cara_Pengendalian':d.get('kontrol','')})

    # V36.4.38 — read Pengawasan Langsir fresh from Buku Kerja using the
    # currently selected weekly period.  Review and PPT now consume this same
    # list, so they cannot diverge because of a stale session-state payload.
    lang_start=st.session_state.get('_v421_weekly_filter_start')
    lang_end=st.session_state.get('_v421_weekly_filter_end')
    lang_rows=_book_langsir_sessions(load_book_data(), start=lang_start, end=lang_end)
    langsir=[sess for _,_,sess in lang_rows]
    return {'ibpr':ibpr,'ibpr_count':len(ibpr),'cctv':cctv,'cctv_count':len(cctv),
            'langsir':langsir,'langsir_count':len(langsir),
            'eval':_v421_eval_pages('weekly'),'eval_count':1}


def _v421_review(rows, title):
    st.markdown(f'### Review {title}')
    if not rows:
        st.info('Tidak ada data Buku Kerja pada periode yang dipilih.')
        return
    st.dataframe(rows, use_container_width=True, hide_index=True)

def _v421_render_ppt_preview(ppt_bytes, key_prefix, max_slides=60):
    """Render the actual generated PPT into slide images for an exact visual preview.

    The preview uses the same PPT builder/template as the final download, so tables,
    borders, fonts, spacing, photos and page breaks are the same as the generated file.
    If LibreOffice is unavailable, the page falls back to the existing HTML review.
    """
    lo = shutil.which('libreoffice') or shutil.which('soffice')
    if not lo:
        st.warning('Preview lembar PPT lengkap membutuhkan LibreOffice pada server. Review data tetap ditampilkan sebagai cadangan.')
        return False
    tmp_root = Path(tempfile.mkdtemp(prefix='dsafe_v421_preview_'))
    try:
        ppt_path = tmp_root / 'preview.pptx'
        out_dir = tmp_root / 'out'
        out_dir.mkdir()
        ppt_path.write_bytes(ppt_bytes)
        cmd=[lo,'--headless','--convert-to','pdf','--outdir',str(out_dir),str(ppt_path)]
        proc=subprocess.run(cmd,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=120)
        pdf_path=out_dir/'preview.pdf'
        if proc.returncode != 0 or not pdf_path.exists():
            st.warning('Preview lembar PPT tidak dapat dirender di server ini. Review data tetap ditampilkan sebagai cadangan.')
            return False
        # pdftoppm is widely available with LibreOffice/Linux images and keeps the
        # 16:9 slide page intact.
        ppm = shutil.which('pdftoppm')
        if not ppm:
            st.warning('Renderer gambar PDF tidak tersedia. Review data tetap ditampilkan sebagai cadangan.')
            return False
        prefix=tmp_root/'slide'
        proc2=subprocess.run([ppm,'-png','-r','120',str(pdf_path),str(prefix)],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=120)
        if proc2.returncode != 0:
            st.warning('Gambar preview PPT gagal dibuat. Review data tetap ditampilkan sebagai cadangan.')
            return False
        images=sorted(tmp_root.glob('slide-*.png'))
        if not images:
            return False
        for idx,img in enumerate(images[:max_slides],1):
            st.image(str(img),caption=f'Lembar PPT {idx}',use_container_width=True)
        return True
    except Exception:
        st.warning('Preview lembar PPT lengkap tidak dapat ditampilkan. Review data tetap ditampilkan sebagai cadangan.')
        return False
    finally:
        # Streamlit copies image data when st.image receives a path, so the temp
        # directory can be removed after rendering.
        shutil.rmtree(tmp_root,ignore_errors=True)

